// Pins the hand-written canonical IR types (ir.ts) to the json2ts mirror of MW1's schema
// (flow.gen.ts, regenerated by scripts/gen_protocol.sh): if the schema changes so that a canonical
// flow is no longer a valid schema flow, `pnpm typecheck` fails here.
import type * as Gen from "./flow.gen";
import type * as PGen from "./project.gen";
import type { Project } from "./project.ts";
import type { Flow, MapBlock, Stmt, Expr, Handler, MapEvent } from "./ir.ts";

type Pin<A, B> = A extends B ? true : false;

export const IR_MATCHES_SCHEMA: [
  Pin<Flow, Gen.Flow>,
  Pin<MapBlock, Gen.MapBlock>,
  Pin<Stmt, Gen.Body[number]>,
  Pin<Expr, Gen.When>,
  Pin<Handler, Gen.Handler>,
  Pin<MapEvent, Gen.Override | Gen.Extend | Gen.Disable | Gen.Add>,
] = [true, true, true, true, true, true];

// the PROJECT (format 3, 2026-11-13): the browser's project.ts against the engine's schema mirror
// (project.gen.ts, made by scripts/gen_protocol.sh from packages/poring_flow/schema/project.schema.json)
export const PROJECT_MATCHES_SCHEMA: [Pin<Project, PGen.Project>] = [true];
